 private void updateStatus(){if(status==null)return;String title="Ready to connect",hint=profiles.isEmpty()?"Add a config to get started.":"Select a server, then tap Connect.";switch(state){case "connected":title="You're connected";hint="Tap the button to disconnect.";break;case "reconnecting":title="Reconnecting…";hint="Keeping the tunnel open while the network recovers.";break;case "starting":title=kind.equals(EngineService.VPN)?"Connecting…":"Preparing test…";hint="Tap again to cancel.";break;case "testing":title="Testing your servers";hint=done+" of "+total+" checked · tap to stop";break;case "stopping":title="Stopping…";hint="Please wait a moment.";break;}
  if(state.equals("idle")&&!lastError.isEmpty()){title="Something needs attention";hint=message(lastError);}status.setText(title);helper.setText(hint);activeLabel.setVisibility((state.equals("connected")||state.equals("reconnecting"))&&!activeName.isEmpty()?View.VISIBLE:View.GONE);activeLabel.setText((state.equals("reconnecting")?"Reconnecting to: ":"Connected to: ")+activeName);sectionBlock.setVisibility(profiles.isEmpty()?View.GONE:View.VISIBLE);power.stateChanged();power.setContentDescription(busy()?"Stop connection or test":"Connect VPN");}
 private interface Edit {void apply(JSONObject d)throws Exception;}
 private void load(){io.execute(()->{try{JSONObject d=new Store(this).transaction(null);apply(d);}catch(Exception e){showError(e);}});}
 private void apply(JSONObject d)throws Exception{List<Profile> p=Store.profiles(d);main.post(()->{if(isDestroyed())return;data=d;profiles=p;Set<String> valid=new HashSet<>();for(Profile profile:p)valid.add(profile.id);results.keySet().retainAll(valid);ranks.keySet().retainAll(valid);working=SubscriptionJob.running();updating=working?SubscriptionJob.current().id:"";rebuild(true);updateStatus();});}
 private boolean canEdit(){if(working){notice("Please wait for the current update.");return false;}if(busy()){notice("Disconnect or stop the test before making changes.");return false;}return true;}
 private void edit(Edit task,FeedbackPolicy.Event event){if(!canEdit())return;working=true;io.execute(()->{try{JSONObject d=new Store(this).transaction(task::apply);apply(d);main.post(()->{if(!isDestroyed())notice(FeedbackPolicy.message(event));});}catch(Exception e){showError(e);}});}
 private void showError(Exception e){String code=Net.error(e);main.post(()->{if(isDestroyed())return;working=false;updating="";rebuild(true);sheet("Couldn't complete this action",(b,d)->{add(b,text(message(code),16,false,muted),-1,-2,0);gap(b,12);add(b,text("Error code: "+code,14,false,muted),-1,-2,0);gap(b,20);add(b,button("Close",0,true,d::dismiss),-1,-2,0);});});}
 private static final class Row {final Profile p;final JSONObject group;final String id,title;final int count;Row(String id,String title,Profile p,JSONObject g,int count){this.id=id;this.title=title;this.p=p;group=g;this.count=count;}String key(){return p!=null?"p:"+p.id:"g:"+id;}}
 private void rebuild(boolean preserve){if(adapter==null)return;if(preserve&&scrollState!=AbsListView.OnScrollListener.SCROLL_STATE_IDLE){pendingRebuild=true;adapter.notifyDataSetChanged();return;}String anchor="";int y=0,index=list.getFirstVisiblePosition();if(preserve&&list.getChildCount()>0){View v=list.getChildAt(0);y=v.getTop();int r=index-1;if(r>=0&&r<rows.size())anchor=rows.get(r).key();}rows.clear();try{List<Profile> manual=new ArrayList<>();for(Profile p:profiles)if(p.group.isEmpty())manual.add(p);if(!manual.isEmpty())append("manual","My configs",manual,null);if(data!=null){JSONArray groups=data.getJSONArray("groups");for(int i=0;i<groups.length();i++){JSONObject g=groups.getJSONObject(i);List<Profile> children=new ArrayList<>();for(Profile p:profiles)if(p.group.equals(g.getString("id")))children.add(p);append(g.getString("id"),g.getString("name"),children,g);}}if(rows.isEmpty())rows.add(new Row("empty","Your first connection",null,null,0));}catch(Exception ignored){}adapter.notifyDataSetChanged();if(preserve){int position=index;if(!anchor.isEmpty())for(int i=0;i<rows.size();i++)if(rows.get(i).key().equals(anchor)){position=i+1;break;}list.setSelectionFromTop(Math.min(position,rows.size()),y);}}
 private void append(String id,String title,List<Profile> found,JSONObject group){rows.add(new Row(id,title,null,group,found.size()));if(!collapsed.contains(id))for(Profile p:SpeedRanker.sort(found,ranks))rows.add(new Row(id,p.name,p,group,0));}
 /** One continuous panel per subscription, independent of recycled row boundaries. */
 private final class GroupPanel extends Drawable {
  private final boolean first,last;private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);private final RectF box=new RectF();private final Path path=new Path();
  GroupPanel(boolean first,boolean last){this.first=first;this.last=last;}
  @Override public void draw(Canvas c){box.set(getBounds());box.inset(dp(1),0);float r=dp(20),t=first?r:0,b=last?r:0;path.reset();path.addRoundRect(box,new float[]{t,t,t,t,b,b,b,b},Path.Direction.CW);paint.setStyle(Paint.Style.FILL);paint.setColor(card);c.drawPath(path,paint);paint.setStyle(Paint.Style.STROKE);paint.setColor(line);paint.setStrokeWidth(dp(1));int save=c.save();c.clipRect(0,first?0:dp(1),getBounds().right,last?getBounds().bottom:getBounds().bottom-dp(1));c.drawPath(path,paint);c.restoreToCount(save);}
  @Override public void setAlpha(int value){} @Override public void setColorFilter(ColorFilter filter){} @Override public int getOpacity(){return PixelFormat.TRANSLUCENT;}
 }
