 private static final class Holder {LinearLayout outer,panel,body,tools;ImageView mark;TextView title,sub,caption;View refresh,test,delete,divider;}
 private String facts(Profile p){JSONObject r=results.get(p.id);if(r==null)r=ranks.get(p.id);if(r==null)return p.protocol.toUpperCase(Locale.ROOT)+" · Not tested";String e=r.optString("error");if(!e.isEmpty())return p.protocol.toUpperCase(Locale.ROOT)+" · Test failed — hold for details";long ping=r.optLong("ping",-1);double speed=r.optDouble("mbps",-1);return (speed>=0?String.format(Locale.US,"%.2f Mbps · ",speed):"")+(ping>=0?ping+" ms · ":"")+p.protocol.toUpperCase(Locale.ROOT);}
 private void deleteGroup(Row r){String copy=r.group==null?"Delete all manually added configs?":"Delete this subscription and all "+r.count+" configs inside it?";confirm("Delete “"+r.title+"”?",copy+" This cannot be undone.","Delete",()->{if(r.group!=null)edit(d->Catalog.deleteGroup(d,r.id),FeedbackPolicy.Event.DELETED);else edit(d->{JSONArray kept=new JSONArray(),a=d.getJSONArray("profiles");for(int i=0;i<a.length();i++)if(!a.getJSONObject(i).optString("group").isEmpty())kept.put(a.get(i));d.put("profiles",kept);},FeedbackPolicy.Event.DELETED);});}
 private void details(Profile p){sheet(p.name,(b,d)->{JSONObject r=results.get(p.id);if(r!=null&&!r.optString("error").isEmpty()){add(b,text(message(r.optString("error"))+"\nError code: "+r.optString("error"),16,false,muted),-1,-2,0);gap(b,14);}add(b,button("Copy config JSON (private)",R.drawable.ic_copy,false,()->{d.dismiss();try{String value=Parser.obj("name",p.name,"outbounds",new JSONArray(p.outbounds)).toString();((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Private Xenet config",value));notice(FeedbackPolicy.message(FeedbackPolicy.Event.PRIVATE_COPIED));}catch(Exception e){notice("Could not copy this config.");}d.dismiss();}),-1,-2,0);});}
